  '==', '!=', '<=', '>=', '&&', '||', '->', '=>',
  '+', '-', '*', '/', '%', '=', '<', '>', '!',
  '(', ')', '{', '}', '[', ']', ',', ';', '.',
]

function nextTabStop(col) {
  return (Math.floor((col - 1) / 4) + 1) * 4 + 1
}

