// Positions count from 1. Tabs advance the column to the next multiple of 4
// plus 1; line feeds move to the next line and reset the column to 1; every
// other code point advances the column by 1.

export class LexError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

