function readStdin() {
  const chunks = []
  const fs = require('node:fs')
  return fs.readFileSync(0, 'utf8')
}

async function main() {
  const mode = process.argv[2]
  if (mode !== 'tokens' && mode !== 'stats') {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }

  const { readFileSync } = await import('node:fs')
  const input = readFileSync(0, 'utf8')

  let tokens
  try {
    tokens = scan(input)
  } catch (e) {
    if (e instanceof LexError) {
      process.stderr.write(`error: ${e.line}:${e.col}: ${e.reason}\n`)
      process.exit(2)
    }
    throw e
  }

  if (mode === 'tokens') {
    let out = ''
    for (const t of tokens) {
      out += `${t.line}:${t.col} ${t.kind} ${t.text}\n`
    }
    process.stdout.write(out)
  } else {
    const kinds = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']
    const counts = Object.fromEntries(kinds.map((k) => [k, 0]))
    for (const t of tokens) counts[t.kind]++
    let out = ''
    for (const k of kinds) out += `${k} ${counts[k]}\n`
    out += `total ${tokens.length}\n`
    process.stdout.write(out)
  }

  process.exit(0)
}

main()
